const roleDeleteDialog=document.createElement('dialog');roleDeleteDialog.innerHTML='<div class="modal-head"><h2>删除角色</h2><button id="closeRoleDelete">✕</button></div><p id="roleDeleteName"></p><p>角色设定及生成历史会移入本项目的角色回收站，可恢复。磁盘图片和其他角色保留。</p><p id="roleDeleteWarning" class="subtle"></p><div class="modal-actions"><button id="cancelRoleDelete">取消</button><button id="confirmRoleDelete" style="background:#573339;color:#ffd8d8">移入角色回收站</button></div>';document.body.append(roleDeleteDialog);let deletingRole=null;
for(const id of ['closeRoleDelete','cancelRoleDelete'])document.querySelector('#'+id).onclick=()=>roleDeleteDialog.close();
function roleIsBusy(c){return multiBusyStates.includes(c.frontJob?.status)||(c.multi||[]).some(v=>Object.values(v.jobs||{}).some(j=>multiBusyStates.includes(j.status)));}
function askDeleteRole(c){deletingRole=c;document.querySelector('#roleDeleteName').textContent='删除「'+c.name+'」？';document.querySelector('#roleDeleteWarning').textContent=roleIsBusy(c)?'该角色还有生成任务，请等待结束后再删除。':'分镜中已有的角色引用会保留；需要时可从回收站恢复该角色。';document.querySelector('#confirmRoleDelete').disabled=roleIsBusy(c);roleDeleteDialog.showModal();}
document.querySelector('#confirmRoleDelete').onclick=()=>{try{if(!deletingRole||roleIsBusy(deletingRole))return;if(typeof diskConflict!=='undefined'&&diskConflict)throw Error('请先导出当前修改并刷新，处理另一个窗口的保存冲突');const index=data.characters.indexOf(deletingRole);if(index<0)throw Error('角色列表已变化，请重新选择');const next=clone(data);next.characterTrash??=[];next.characterTrash.unshift({trash_id:crypto.randomUUID(),deleted_at:new Date().toISOString(),character:clone(deletingRole),original_index:index});next.characters.splice(index,1);localStorage.setItem(key,JSON.stringify(next));data=next;ci=Math.min(index,Math.max(0,data.characters.length-1));save();roleDeleteDialog.close();render();toast('角色已移入回收站，生成文件保留')}catch(e){toast(e.message)}};
const roleTrashDialog=document.createElement('dialog');roleTrashDialog.innerHTML='<div class="modal-head"><h2>角色回收站</h2><button id="closeRoleTrash">✕</button></div><div id="roleTrashItems"></div>';document.body.append(roleTrashDialog);document.querySelector('#closeRoleTrash').onclick=()=>roleTrashDialog.close();
function showRoleTrash(){const list=document.querySelector('#roleTrashItems');list.replaceChildren();const items=data.characterTrash||[];if(!items.length)list.textContent='暂无已删除角色。';for(const item of items){const row=document.createElement('div');row.className='card';row.style.marginBottom='10px';const title=document.createElement('p');title.textContent=item.character.name+' · '+new Date(item.deleted_at).toLocaleString('zh-CN');const button=document.createElement('button');button.textContent='恢复角色';button.onclick=()=>{try{if(typeof diskConflict!=='undefined'&&diskConflict)throw Error('请先处理保存冲突');if(data.characters.some(c=>(c.id&&c.id===item.character.id)||c.name===item.character.name))throw Error('当前已有同 ID 或同名角色，请先处理重复角色');const next=clone(data);next.characters.splice(Math.min(item.original_index,next.characters.length),0,item.character);next.characterTrash=next.characterTrash.filter(t=>t.trash_id!==item.trash_id);localStorage.setItem(key,JSON.stringify(next));data=next;ci=data.characters.findIndex(c=>c.name===item.character.name);save();roleTrashDialog.close();render();toast('角色与生成历史已恢复')}catch(e){toast(e.message)}};row.append(title,button);list.append(row)}roleTrashDialog.showModal();}
const charactersBeforeRoleActions=characters;
characters=function(){charactersBeforeRoleActions();const c=data.characters[ci];const head=document.querySelector('#panel .section-head');const trash=document.createElement('button');trash.textContent='角色回收站';trash.style.fontSize='11px';trash.onclick=showRoleTrash;if(head){head.lastElementChild.append(trash)}else document.querySelector('#panel').prepend(trash);if(c){const heading=document.querySelector('#charName')?.closest('.card')?.querySelector('.right-title');if(heading){heading.style.cssText+=';display:flex;align-items:center;justify-content:space-between;gap:12px';const remove=document.createElement('button');remove.textContent='删除角色';remove.setAttribute('aria-label','删除当前角色 '+c.name);remove.className='text';remove.style.cssText='font-size:11px;color:#f1b6b6;padding:3px 0;font-weight:400';remove.onclick=()=>askDeleteRole(c);heading.append(remove);}}if(c){const role=document.querySelector('#charRole');if(role){role.value=({protagonist:'主角',deuteragonist:'第二主角',emotional_lead:'核心情感角色',supporting:'配角',antagonist:'冲突角色'})[c.role]||c.role;role.title='原始角色身份：'+c.role;}const desc=document.querySelector('#charDesc');if(desc){let display=desc.value;for(const [code,label] of [['municipal_street_cleaning_robot','市政道路清扫机器人'],['robot','机器人'],['human','人类']])display=display.split('；').map(v=>v===code?label:v).join('；');const a=c.appearance||{};const size=[a.length_cm?'长 '+a.length_cm+' cm':null,a.width_cm?'宽 '+a.width_cm+' cm':null,a.height_cm?'高 '+a.height_cm+' cm':null].filter(Boolean).join(' × ');if(size&&!display.includes(size))display=size+'；'+display;desc.value=display;}}};render();
